import { getWarnings, prebuild, setWarningsSilent, StrictModeError, } from '@mintlify/prebuild';
import fse, { pathExists } from 'fs-extra';
import { CLIENT_PATH, CMD_EXEC_PATH, VERSION_PATH, NEXT_PUBLIC_PATH, NEXT_PROPS_PATH, PREVIEW_PATH, configureSharedPreviewPath, } from '../constants.js';
import { timeDev, timeDevSync } from './dev-timing.js';
import { isOnline } from './is-online.js';
import { silentUpdateClient } from './update.js';
/**
 * Runs the strict prebuild and returns its result without logging: warnings are collected
 * instead of printed.
 */
export const checkBuild = async (argv) => {
    configureSharedPreviewPath();
    const hasInternet = await timeDev('check internet', () => isOnline());
    const localSchema = argv['local-schema'];
    const clientVersion = argv['client-version'];
    const packageName = argv.packageName;
    const groups = argv.groups;
    const cliVersion = argv.cliVersion;
    const disableOpenApi = argv.disableOpenapi;
    await timeDev('ensure preview directory', () => fse.ensureDir(PREVIEW_PATH));
    const versionString = await timeDev('read local client version', async () => {
        return (await pathExists(VERSION_PATH)) ? fse.readFileSync(VERSION_PATH, 'utf8') : null;
    });
    if (!versionString && !hasInternet) {
        throw new Error(`running ${packageName} validate after updating requires an internet connection.`);
    }
    const { error } = await timeDev('update local client', () => silentUpdateClient({
        versionString,
        clientVersion,
        cliVersion,
        localClientVersion: undefined,
    }));
    if (error) {
        throw new Error(error);
    }
    // clear preexisting prebuild files
    timeDevSync('clear prebuild output', () => {
        fse.emptyDirSync(NEXT_PUBLIC_PATH);
        fse.emptyDirSync(NEXT_PROPS_PATH);
    });
    const cwd = process.cwd();
    timeDevSync('switch to local client directory', () => {
        process.chdir(CLIENT_PATH);
    });
    const runPrebuild = () => timeDev('prebuild content', () => prebuild(CMD_EXEC_PATH, {
        localSchema,
        groups,
        disableOpenApi,
        strict: true,
        skipStaticFiles: true,
    }));
    setWarningsSilent(true);
    try {
        await runPrebuild();
        return { passed: true, warnings: getWarnings() };
    }
    catch (err) {
        const errorText = err instanceof Error && err.message ? err.message : 'build validation failed';
        return {
            passed: false,
            error: errorText,
            strict: err instanceof StrictModeError,
            warnings: getWarnings(),
        };
    }
    finally {
        setWarningsSilent(false);
        process.chdir(cwd);
    }
};
